<template><section><div class="flex justify-between mb-6"><h2 class="text-2xl font-bold">Cây trồng</h2><router-link class="px-4 py-2 rounded bg-primary text-secondary" :to="{name:'admin-crop-create'}">Thêm cây trồng</router-link></div><p v-if="error" class="text-error">{{error}}</p><p v-else-if="loading" class="text-gray-400">Đang tải…</p><Table v-else :columns="columns" :data="crops"><template #actions="{row}"><router-link class="text-primary" :to="{name:'admin-crop-edit',params:{id:row.cropId}}">Chỉnh sửa</router-link></template></Table><div v-if="!loading" class="mt-4 flex justify-between text-sm text-gray-400"><span>Tổng {{total}} cây trồng</span><div class="flex gap-3"><button :disabled="page===0" @click="page--;load()">Trước</button><span>Trang {{page+1}} / {{Math.max(totalPages,1)}}</span><button :disabled="page+1>=totalPages" @click="page++;load()">Sau</button></div></div></section></template><script setup>import{onMounted,ref}from'vue';import Table from'../../components/ui/Table.vue';import{adminApi}from'../../api/adminService';const crops=ref([]),loading=ref(true),error=ref(''),page=ref(0),total=ref(0),totalPages=ref(0);const columns=[{key:'cropId',label:'Mã'},{key:'cropName',label:'Tên cây trồng'},{key:'actions',label:'Thao tác'}];const load=async()=>{loading.value=true;error.value='';try{const{data}=await adminApi.cropPage({page:page.value,size:10,sort:'cropId,asc'});crops.value=data.content;total.value=data.totalElements;totalPages.value=data.totalPages}catch(e){error.value=e.response?.data?.message||'Không thể tải cây trồng.'}finally{loading.value=false}};onMounted(load)</script>
